// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    Receiver recv;

    function setUp() public { c = new MultiplicatorX4(); recv = new Receiver(); }

    function testFuzz_property(address caller, uint256 value) public {
        vm.assume(caller != address(0));
        value = bound(value, 0, 1 ether);

        vm.deal(address(this), value);

        address target = address(recv);

        bool ok;
        try c.Command{value: value}(target, "") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(recv.lastReceived() == value);
    }
}

contract Receiver {
    uint256 public lastReceived;

    receive() external payable {
        lastReceived = msg.value;
    }
    fallback() external payable {
        lastReceived = msg.value;
    }
}
